dashboard.definition:
{
    "title": "Threat Detection and Enforcement",
    "description": "Track high-confidence detections and verify the controls enforcing policy.",
    "inputs": {
        "input_time_range": {
            "options": {
                "defaultValue": "-24h@h,now,auto",
                "showAdvanced": true,
                "selections": [
                    {
                        "value": "-4h,now,auto",
                        "label": "4h"
                    },
                    {
                        "value": "-24h@h,now,auto",
                        "label": "24h"
                    },
                    {
                        "value": "-48h,now,auto",
                        "label": "48h"
                    },
                    {
                        "value": "-7d@d,now,auto",
                        "label": "7d"
                    },
                    {
                        "value": "-30d@d,now,auto",
                        "label": "30d"
                    }
                ],
                "token": "time_tok"
            },
            "title": "Time range",
            "type": "input.simpleTimePicker"
        }
    },
    "defaults": {
        "visualizations": {
            "global": {
                "showLastUpdated": true,
                "showProgressBar": true
            }
        }
    },
    "visualizations": {
        "viz_header_bg": {
            "type": "splunk.rectangle",
            "options": {
                "fillColor": "#1c2738",
                "strokeColor": "rgba(100,158,245,0.28)",
                "rx": 10
            }
        },
        "viz_header_icon": {
            "type": "splunk.image",
            "title": "Threat Detection and Enforcement",
            "options": {
                "preserveAspectRatio": true,
                "src": "/static/app/splunk-cisco-dashboards/images/nav-icons/ArrowsDoubleLeftRight.svg"
            }
        },
        "viz_header": {
            "type": "splunk.markdown",
            "title": "",
            "showLastUpdated": false,
            "showProgressBar": false,
            "options": {
                "backgroundColor": "transparent",
                "fontColor": "#ecf0f5",
                "markdown": "# Threat Detection and Enforcement\nTrack high\\-confidence detections and verify the controls enforcing policy\\."
            }
        },
        "viz_card_01_background": {
            "type": "splunk.rectangle",
            "options": {
                "fillColor": "#131a23",
                "strokeColor": "rgba(100,158,245,0.28)",
                "rx": 12
            }
        },
        "viz_card_01_title": {
            "type": "splunk.markdown",
            "title": "",
            "showLastUpdated": false,
            "showProgressBar": false,
            "options": {
                "backgroundColor": "transparent",
                "fontColor": "#ecf0f5",
                "fontSize": "custom",
                "customFontSize": 20,
                "markdown": "**Firewall Decisions**"
            }
        },
        "viz_card_01_metadata": {
            "type": "splunk.markdown",
            "title": "",
            "showLastUpdated": false,
            "showProgressBar": false,
            "options": {
                "backgroundColor": "transparent",
                "fontColor": "#649ef5",
                "fontSize": "custom",
                "customFontSize": 14,
                "markdown": "Network  •  Hybrid Mesh Firewalling"
            }
        },
        "viz_card_01_description": {
            "type": "splunk.markdown",
            "title": "",
            "showLastUpdated": false,
            "showProgressBar": false,
            "options": {
                "backgroundColor": "transparent",
                "fontColor": "#a6adb6",
                "fontSize": "custom",
                "customFontSize": 15,
                "markdown": "Compares Blocked and Allowed traffic decisions from the accelerated Network Traffic data model across the selected window\\."
            }
        },
        "viz_card_01_singlevalue": {
            "type": "splunk.singlevalue",
            "title": "",
            "dataSources": {
                "primary": "ds_story_01"
            },
            "showLastUpdated": false,
            "showProgressBar": false,
            "options": {
                "backgroundColor": "transparent",
                "majorColor": "#ecf0f5",
                "majorFontSize": 44,
                "majorValue": "> primary | seriesByName(\"WindowTotal\") | lastPoint() | divideBy(0.999999999999)",
                "shouldAbbreviateMajorValue": true,
                "sparklineDisplay": "off",
                "trendDisplay": "off",
                "showTrendIndicator": false,
                "sparklineValues": "> primary | seriesByName(\"Connections\")",
                "unit": " connections",
                "unitPosition": "after"
            }
        },
        "viz_card_01_trend": {
            "type": "splunk.column",
            "title": "",
            "dataSources": {
                "primary": "ds_story_01"
            },
            "showLastUpdated": false,
            "showProgressBar": false,
            "options": {
                "backgroundColor": "transparent",
                "legendDisplay": "off",
                "seriesColors": [
                    "#e44273",
                    "#3abdfa",
                    "#0d8e97",
                    "#e2a811",
                    "#9b5ff4",
                    "#a9afda",
                    "#d8580f",
                    "#f88ddc",
                    "#159352",
                    "#9abe2d",
                    "#6574f3",
                    "#ff9297",
                    "#d14baf",
                    "#24c4c9",
                    "#bb6e04",
                    "#6ec641",
                    "#777daf",
                    "#ff9755",
                    "#698c07",
                    "#c69fff"
                ],
                "dataValuesDisplay": "all",
                "showYMajorGridLines": false,
                "stackMode": "unstacked",
                "xAxisTitleVisibility": "hide",
                "yAxisTitleVisibility": "hide",
                "x": "> primary | seriesByName(\"Decision\")",
                "y": "> primary | seriesByName(\"Connections\")",
                "showYMinorGridLines": false,
                "yAxisLabelVisibility": "hide",
                "yAxisLineVisibility": "hide",
                "yAxisMajorTickVisibility": "hide",
                "yAxisMinorTickVisibility": "hide"
            }
        },
        "viz_card_01_drilldown_trigger": {
            "type": "splunk.rectangle",
            "eventHandlers": [
                {
                    "type": "drilldown.customUrl",
                    "options": {
                        "url": "/drilldown?origin=Firewall%20Decisions&target=Security%20Resilience%20-%20Firewall%20Base%20Search,Secure%20Networking%20-%20FMC%20Blocked%20Connection%20Detail,security_firewall_nat_resource_failure_evidence,network_firewall_nat_tuple_concentration,security_firewall_low_activity_observed_rules,mv_pan_denied_zone_boundaries,mv_fortinet_policy_denials,mv_junos_srx_denials,mv_checkpoint_denied_services,mv_checkpoint_rule_action_inventory,mv_checkpoint_nat_observed_addresses,mv_ipv6_decision_visibility,network_cross_vendor_decision_field_coverage"
                    }
                }
            ],
            "options": {
                "fillColor": "transparent",
                "strokeColor": "transparent"
            },
            "context": {},
            "containerOptions": {},
            "showProgressBar": false,
            "showLastUpdated": false
        },
        "viz_card_01_info_trigger": {
            "type": "splunk.rectangle",
            "eventHandlers": [
                {
                    "type": "drilldown.customUrl",
                    "options": {
                        "url": "/metric-info?origin=Firewall%20Decisions&target=network_intelligence_blocked_vs_allowed"
                    }
                }
            ],
            "options": {
                "fillColor": "transparent",
                "strokeColor": "transparent"
            },
            "context": {},
            "containerOptions": {},
            "showProgressBar": false,
            "showLastUpdated": false
        },
        "viz_card_02_background": {
            "type": "splunk.rectangle",
            "options": {
                "fillColor": "#131a23",
                "strokeColor": "rgba(100,158,245,0.28)",
                "rx": 12
            }
        },
        "viz_card_02_title": {
            "type": "splunk.markdown",
            "title": "",
            "showLastUpdated": false,
            "showProgressBar": false,
            "options": {
                "backgroundColor": "transparent",
                "fontColor": "#ecf0f5",
                "fontSize": "custom",
                "customFontSize": 20,
                "markdown": "**Cloud Firewall Blocks**"
            }
        },
        "viz_card_02_metadata": {
            "type": "splunk.markdown",
            "title": "",
            "showLastUpdated": false,
            "showProgressBar": false,
            "options": {
                "backgroundColor": "transparent",
                "fontColor": "#649ef5",
                "fontSize": "custom",
                "customFontSize": 14,
                "markdown": "Security  •  Cloud Security"
            }
        },
        "viz_card_02_description": {
            "type": "splunk.markdown",
            "title": "",
            "showLastUpdated": false,
            "showProgressBar": false,
            "options": {
                "backgroundColor": "transparent",
                "fontColor": "#a6adb6",
                "fontSize": "custom",
                "customFontSize": 15,
                "markdown": "Counts unique cloud firewall blocks as distinct source, destination, and port tuples from Secure Access or Umbrella web firewall telemetry\\."
            }
        },
        "viz_card_02_singlevalue": {
            "type": "splunk.singlevalue",
            "title": "",
            "dataSources": {
                "primary": "ds_story_02"
            },
            "showLastUpdated": false,
            "showProgressBar": false,
            "options": {
                "backgroundColor": "transparent",
                "majorColor": "#ecf0f5",
                "majorFontSize": 44,
                "majorValue": "> primary | seriesByName(\"WindowUniqueBlockedFlows\") | lastPoint() | divideBy(0.999999999999)",
                "shouldAbbreviateMajorValue": true,
                "sparklineDisplay": "off",
                "trendDisplay": "absolute",
                "shouldAbbreviateTrendValue": true,
                "showTrendIndicator": true,
                "sparklineValues": "> primary | seriesByName(\"count\")",
                "trendColor": "> trendValue | rangeValue(trendColorEditorConfig)",
                "trendFontSize": 28,
                "trendValue": "> sparklineValues | delta(-2)",
                "unit": " unique flows",
                "unitPosition": "after"
            },
            "context": {
                "trendColorEditorConfig": [
                    {
                        "value": "#049fd9",
                        "to": 0
                    },
                    {
                        "value": "#049fd9",
                        "from": 0
                    }
                ]
            }
        },
        "viz_card_02_trend": {
            "type": "splunk.column",
            "title": "",
            "dataSources": {
                "primary": "ds_story_02"
            },
            "showLastUpdated": false,
            "showProgressBar": false,
            "options": {
                "backgroundColor": "transparent",
                "legendDisplay": "off",
                "seriesColors": [
                    "#9b5ff4",
                    "#3abdfa",
                    "#0d8e97",
                    "#e2a811",
                    "#e44273",
                    "#a9afda",
                    "#d8580f",
                    "#f88ddc",
                    "#159352",
                    "#9abe2d",
                    "#6574f3",
                    "#ff9297",
                    "#d14baf",
                    "#24c4c9",
                    "#bb6e04",
                    "#6ec641",
                    "#777daf",
                    "#ff9755",
                    "#698c07",
                    "#c69fff"
                ],
                "dataValuesDisplay": "off",
                "showYMajorGridLines": false,
                "showYMinorGridLines": false,
                "stackMode": "unstacked",
                "xAxisTitleVisibility": "hide",
                "x": "> primary | seriesByName(\"_time\")",
                "y": "> primary | seriesByName(\"count\")",
                "yAxisLabelVisibility": "hide",
                "yAxisLineVisibility": "hide",
                "yAxisMajorTickVisibility": "hide",
                "yAxisMinorTickVisibility": "hide",
                "yAxisTitleVisibility": "hide"
            }
        },
        "viz_card_02_drilldown_trigger": {
            "type": "splunk.rectangle",
            "eventHandlers": [
                {
                    "type": "drilldown.customUrl",
                    "options": {
                        "url": "/drilldown?origin=Cloud%20Firewall%20Blocks&target=Secure%20Networking%20-%20SSE%20Security%20Event%20Detail"
                    }
                }
            ],
            "options": {
                "fillColor": "transparent",
                "strokeColor": "transparent"
            },
            "context": {},
            "containerOptions": {},
            "showProgressBar": false,
            "showLastUpdated": false
        },
        "viz_card_02_info_trigger": {
            "type": "splunk.rectangle",
            "eventHandlers": [
                {
                    "type": "drilldown.customUrl",
                    "options": {
                        "url": "/metric-info?origin=Cloud%20Firewall%20Blocks&target=security_resilience_cloud_fw_blocked"
                    }
                }
            ],
            "options": {
                "fillColor": "transparent",
                "strokeColor": "transparent"
            },
            "context": {},
            "containerOptions": {},
            "showProgressBar": false,
            "showLastUpdated": false
        },
        "viz_card_03_background": {
            "type": "splunk.rectangle",
            "options": {
                "fillColor": "#131a23",
                "strokeColor": "rgba(100,158,245,0.28)",
                "rx": 12
            }
        },
        "viz_card_03_title": {
            "type": "splunk.markdown",
            "title": "",
            "showLastUpdated": false,
            "showProgressBar": false,
            "options": {
                "backgroundColor": "transparent",
                "fontColor": "#ecf0f5",
                "fontSize": "custom",
                "customFontSize": 20,
                "markdown": "**Multicloud Deny Rate**"
            }
        },
        "viz_card_03_metadata": {
            "type": "splunk.markdown",
            "title": "",
            "showLastUpdated": false,
            "showProgressBar": false,
            "options": {
                "backgroundColor": "transparent",
                "fontColor": "#649ef5",
                "fontSize": "custom",
                "customFontSize": 14,
                "markdown": "Security  •  Cloud Security"
            }
        },
        "viz_card_03_description": {
            "type": "splunk.markdown",
            "title": "",
            "showLastUpdated": false,
            "showProgressBar": false,
            "options": {
                "backgroundColor": "transparent",
                "fontColor": "#a6adb6",
                "fontSize": "custom",
                "customFontSize": 15,
                "markdown": "Single\\-value deny rate across all Cisco Multicloud Defense security event subtypes \\(WAF, AV, DLP, URL/FQDN filter, L4 FW, L7 DoS, malicious source, SNI, TLS, DPI\\)\\. Excludes audit logs and gateway system logs\\."
            }
        },
        "viz_card_03_singlevalue": {
            "type": "splunk.singlevalue",
            "title": "",
            "dataSources": {
                "primary": "ds_story_03"
            },
            "showLastUpdated": false,
            "showProgressBar": false,
            "options": {
                "backgroundColor": "transparent",
                "majorColor": "#ecf0f5",
                "majorFontSize": 44,
                "majorValue": "> primary | seriesByName(\"WindowDenyPct\") | lastPoint() | divideBy(0.999999999999)",
                "shouldAbbreviateMajorValue": true,
                "sparklineDisplay": "off",
                "trendDisplay": "absolute",
                "shouldAbbreviateTrendValue": true,
                "showTrendIndicator": true,
                "sparklineValues": "> primary | seriesByName(\"deny_pct\")",
                "trendColor": "> trendValue | rangeValue(trendColorEditorConfig)",
                "trendFontSize": 28,
                "trendValue": "> sparklineValues | delta(-2)",
                "unit": " %",
                "unitPosition": "after"
            },
            "context": {
                "trendColorEditorConfig": [
                    {
                        "value": "#049fd9",
                        "to": 0
                    },
                    {
                        "value": "#049fd9",
                        "from": 0
                    }
                ]
            }
        },
        "viz_card_03_trend": {
            "type": "splunk.line",
            "title": "",
