                "y": "> primary | seriesByName(\"deny_pct\")",
                "showYMinorGridLines": false,
                "yAxisLabelVisibility": "hide",
                "yAxisLineVisibility": "hide",
                "yAxisMajorTickVisibility": "hide",
                "yAxisMinorTickVisibility": "hide"
            }
        },
        "viz_card_03_drilldown_trigger": {
            "type": "splunk.rectangle",
            "eventHandlers": [
                {
                    "type": "drilldown.customUrl",
                    "options": {
                        "url": "/drilldown?origin=Multicloud%20Deny%20Rate&target=Security%20-%20Cloud%20Security%20-%20Multicloud%20Defense%20Recent%20WAF%20Findings,Security%20-%20Cloud%20Security%20-%20Multicloud%20Defense%20Gateway%20Health"
                    }
                }
            ],
            "options": {
                "fillColor": "transparent",
                "strokeColor": "transparent"
