                "markdown": "Time series of UTD IPS events bucketed by Snort Priority as Low / Medium / High risk\\. Mirrors the Intrusion Prevention chart on Monitor → Security\\."
            }
        },
        "viz_card_05_singlevalue": {
            "type": "splunk.singlevalue",
            "title": "",
            "dataSources": {
                "primary": "ds_story_05"
            },
            "showLastUpdated": false,
            "showProgressBar": false,
            "options": {
                "backgroundColor": "transparent",
                "majorColor": "#ecf0f5",
